  if ("error" in parsed) {
    writeUsageFailure(deps, parsed.error, json);
    return 2;
  }
  if (parsed.positionals.length > 0) {
    writeUsageFailure(deps, `Unexpected argument: ${parsed.positionals[0]}`, json);
    return 2;
  }
  const keepKey = parsed.booleans.has("--keep-key");
